-- {FINAL} for 11_ (slim, used for Blizzard per day): d|grp|n|clean| then per rule r0..r11 'F,Fh,Fv,Fcl'. Cells with no fire omitted.
SELECT d||'|'||grp||'|'||COUNT(*)||'|'||SUM(cl)||'|'||SUM(r0)||','||SUM(r0*hi)||','||SUM(r0*ver)||','||SUM(r0*cl)||'|'||SUM(r1)||','||SUM(r1*hi)||','||SUM(r1*ver)||','||SUM(r1*cl)||'|'||SUM(r2)||','||SUM(r2*hi)||','||SUM(r2*ver)||','||SUM(r2*cl)||'|'||SUM(r3)||','||SUM(r3*hi)||','||SUM(r3*ver)||','||SUM(r3*cl)||'|'||SUM(r4)||','||SUM(r4*hi)||','||SUM(r4*ver)||','||SUM(r4*cl)||'|'||SUM(r5)||','||SUM(r5*hi)||','||SUM(r5*ver)||','||SUM(r5*cl)||'|'||SUM(r6)||','||SUM(r6*hi)||','||SUM(r6*ver)||','||SUM(r6*cl)||'|'||SUM(r7)||','||SUM(r7*hi)||','||SUM(r7*ver)||','||SUM(r7*cl)||'|'||SUM(r8)||','||SUM(r8*hi)||','||SUM(r8*ver)||','||SUM(r8*cl)||'|'||SUM(r9)||','||SUM(r9*hi)||','||SUM(r9*ver)||','||SUM(r9*cl)||'|'||SUM(r10)||','||SUM(r10*hi)||','||SUM(r10*ver)||','||SUM(r10*cl)||'|'||SUM(r11)||','||SUM(r11*hi)||','||SUM(r11*ver)||','||SUM(r11*cl) r FROM s4 GROUP BY d, grp HAVING SUM(r2+r3+r4+r5+r6+r7+r8+r9)>0
